<template><div><PageHeader title="Learners" description="Manage learner records, enrollment history and training progress."><template #actions><button class="btn secondary" @click="imported=true">Import</button><button class="btn primary" @click="addOpen=true">+ Add learner</button></template></PageHeader><div class="card"><div class="toolbar"><div class="toolbar-left"><input v-model="search" class="input search-input" placeholder="Search learners..."><select class="select" v-model="statusFilter"><option value="all">All status</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div class="toolbar-right"><button class="btn secondary small">Export</button></div></div><DataTable :headers="['Learner','Course','Company','Attendance','Status','']" :actions="true"><tr v-for="learner in filtered" :key="learner.id"><td><RouterLink :to="`/app/learners/${learner.id}`" class="row-person"><Avatar :name="learner.name" size="sm"/><div><strong>{{learner.name}}</strong><span>{{learner.email}}</span></div></RouterLink></td><td>{{learner.course}}</td><td>{{learner.company}}</td><td style="min-width:130px"><div class="course-bottom-line"><span>{{learner.attendance}}%</span><span>attendance</span></div><div class="progress"><span :style="{width:`${learner.attendance}%`}"></span></div></td><td><StatusBadge :status="learner.status"/></td><td><RouterLink class="btn secondary small" :to="`/app/learners/${learner.id}`">Open</RouterLink></td></tr></DataTable></div><Modal :open="addOpen" title="Add learner" description="Create a learner profile for this organization" size="lg" @close="addOpen=false"><form class="form-grid" @submit.prevent="save"><div class="field"><label>First name</label><input class="input" v-model="form.first"></div><div class="field"><label>Last name</label><input class="input" v-model="form.last"></div><div class="field"><label>Email</label><input class="input" v-model="form.email" type="email"></div><div class="field"><label>Phone</label><input class="input" v-model="form.phone"></div><div class="field"><label>Company</label><input class="input" v-model="form.company"></div><div class="field"><label>Status</label><select class="select" v-model="form.status"><option>active</option><option>inactive</option></select></div><div class="form-actions" style="grid-column:1/-1;padding:16px 0 0;border:0"><button type="button" class="btn secondary" @click="addOpen=false">Cancel</button><button type="submit" class="btn primary">Create learner</button></div></form></Modal><Modal :open="imported" title="Import learners" description="CSV import UI placeholder for the Laravel API" @close="imported=false"><div class="empty-state" style="padding:30px 0"><div class="empty-icon">↑</div><h3>Drop a CSV file here</h3><p>The backend endpoint can validate and bulk-import learner records.</p><button class="btn primary" @click="imported=false">Choose CSV</button></div></Modal></div></template>
<script setup lang="ts">import {computed,reactive,ref} from 'vue';import PageHeader from '../components/PageHeader.vue';import DataTable from '../components/DataTable.vue';import Avatar from '../components/Avatar.vue';import StatusBadge from '../components/StatusBadge.vue';import Modal from '../components/Modal.vue';import {learners} from '../data/mock';import {useToast} from '../composables/useToast';const search=ref(''),statusFilter=ref('all'),addOpen=ref(false),imported=ref(false);const {push}=useToast();const form=reactive({first:'',last:'',email:'',phone:'',company:'',status:'active'});const filtered=computed(()=>learners.filter(l=>(statusFilter.value==='all'||l.status===statusFilter.value)&&`${l.name} ${l.email} ${l.company}`.toLowerCase().includes(search.value.toLowerCase())));function save(){addOpen.value=false;push(`${form.first||'Learner'} created successfully.`)}</script>
